#include <cstdint>
#include <format>
#include <iostream>
#include <string>

// Where one participant listens, from the port formula of the DDSI-RTPS specification with the
// constants the ROS 2 documentation on the domain id uses.
struct Endpoint {
  std::int32_t domain;       // ROS_DOMAIN_ID
  std::int32_t participant;  // index of the participant on this computer, counted from 0
};

struct Ports {
  std::int32_t discovery_multicast;
  std::int32_t user_multicast;
  std::int32_t discovery_unicast;
  std::int32_t user_unicast;
};

[[nodiscard]] constexpr Ports ports_of(Endpoint where) {
  constexpr std::int32_t base = 7400;          // PB, the port base
  constexpr std::int32_t per_domain = 250;     // DG, the domain gain
  constexpr std::int32_t per_participant = 2;  // PG, the participant gain
  const std::int32_t domain_base = base + per_domain * where.domain;
  return Ports{.discovery_multicast = domain_base,
               .user_multicast = domain_base + 1,
               .discovery_unicast = domain_base + 10 + per_participant * where.participant,
               .user_unicast = domain_base + 11 + per_participant * where.participant};
}

int main() {
  constexpr std::int32_t ephemeral_low = 32768;  // the Linux default of ip_local_port_range
  for (const Endpoint where : {Endpoint{.domain = 0, .participant = 0},
                               Endpoint{.domain = 1, .participant = 0},
                               Endpoint{.domain = 1, .participant = 119},
                               Endpoint{.domain = 1, .participant = 120},
                               Endpoint{.domain = 2, .participant = 0},
                               Endpoint{.domain = 101, .participant = 54}}) {
    const Ports ports = ports_of(where);
    const Ports next_domain = ports_of(Endpoint{.domain = where.domain + 1, .participant = 0});
    std::string note;
    if (ports.user_unicast >= ephemeral_low) {
      note = "  <- inside the ephemeral range";
    } else if (ports.discovery_unicast >= next_domain.discovery_multicast) {
      note = "  <- on top of the next domain";
    }
    std::cout << std::format("domain {:>3}, participant {:>3}: multicast {} {}, unicast {} {}{}\n", where.domain,
                             where.participant, ports.discovery_multicast, ports.user_multicast,
                             ports.discovery_unicast, ports.user_unicast, note);
  }
}

#include <chrono>
#include <cstddef>
#include <cstdint>
#include <memory>
#include <utility>
#include <vector>

#include <rclcpp/rclcpp.hpp>
#include <sensor_msgs/msg/laser_scan.hpp>

using namespace std::chrono_literals;

// Fills a scan with a fixed pattern. No ROS types in the arithmetic, so a test drives it.
class ScanPattern {
 public:
  explicit ScanPattern(std::ptrdiff_t beams) : beams_(beams) {}

  [[nodiscard]] std::vector<float> ranges(std::int64_t tick) const {
    std::vector<float> values(static_cast<std::size_t>(beams_));
    for (std::ptrdiff_t i = 0; i < beams_; ++i) {
      values[static_cast<std::size_t>(i)] = 1.0F + 0.001F * static_cast<float>((tick + i) % 1000);
    }
    return values;
  }

 private:
  std::ptrdiff_t beams_;
};

class ScanSource : public rclcpp::Node {
 public:
  explicit ScanSource(const rclcpp::NodeOptions& options = rclcpp::NodeOptions()) : Node("scan_source", options) {
    publisher_ = create_publisher<sensor_msgs::msg::LaserScan>("scan", rclcpp::SensorDataQoS());
    const bool intra_process = get_node_options().use_intra_process_comms();
    // A loan goes straight to the middleware and skips the intra-process path, so take it only
    // when that path is off. The two are separate routes, and they do not combine.
    lend_ = publisher_->can_loan_messages() && !intra_process;
    RCLCPP_INFO(get_logger(), "middleware can loan: %s, intra-process: %s, publishing loans: %s",
                publisher_->can_loan_messages() ? "yes" : "no", intra_process ? "on" : "off",
                lend_ ? "yes" : "no");
    timer_ = create_timer(100ms, [this] { publish_scan(); });
  }

 private:
  void publish_scan() {
    ++tick_;
    if (lend_) {
      // The middleware owns this buffer, and a subscriber in another process on this machine
      // can read it without a copy.
      auto loaned = publisher_->borrow_loaned_message();
      fill(loaned.get());
      publisher_->publish(std::move(loaned));
      return;
    }
    auto message = std::make_unique<sensor_msgs::msg::LaserScan>();
    fill(*message);
    publisher_->publish(std::move(message));  // a unique_ptr, so intra-process delivery moves it
  }

  void fill(sensor_msgs::msg::LaserScan& scan) const {
    scan.header.stamp = now();
    scan.header.frame_id = "base_scan";
    scan.range_min = 0.1F;
    scan.range_max = 10.0F;
    scan.ranges = pattern_.ranges(tick_);
  }

  ScanPattern pattern_{360};
  std::int64_t tick_ = 0;
  bool lend_ = false;
  rclcpp::Publisher<sensor_msgs::msg::LaserScan>::SharedPtr publisher_;
  rclcpp::TimerBase::SharedPtr timer_;
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<ScanSource>());
  rclcpp::shutdown();
}
